-- =========================================================================
-- 1. HYPRGLASS PLUGIN SETUP (Top-level scope: re-evaluates on hyprctl reload)
-- =========================================================================
if hl and hl.plugin and hl.plugin.hyprglass then
  local hg = hl.plugin.hyprglass

  -- 1. Define Presets
  hg.preset("hard_blur", {
    glass_opacity = 0.9,
    blur_strength = 0.7,
    blur_iterations = 7,
    refraction_strength = 0.3,
    chromatic_aberration = 0.3,
    fresnel_strength = 4.0,
    specular_strength = 0.3,
    lens_distortion = 0.1,
    dark = { brightness = 1.1, contrast = 1.3, saturation = 1.2 },
  })

  hg.preset("frosted_glass", {
    glass_opacity = 1.2,

    -- Smooth, high-pass blur
    blur_strength = 0.8,
    blur_iterations = 5,           -- Extra passes for ultra-smooth blur

    -- Subtle Tint (RGBA Hex: #111625 at ~12% opacity)
    --tint_color = 0x1116251F,       -- Soft dark-slate tint

    -- Optics & Material Highlights
    refraction_strength = 0.04,
    chromatic_aberration = 0.02,
    fresnel_strength = 0.20,
    specular_strength = 0.10,
    lens_distortion = 0.0,

    -- Background Post-Processing
    dark = {
      brightness = 1.2,
      contrast = 1.08,
      saturation = 1.15,
    },
  })


  -- 2. Apply Global Plugin Config
  hg.config({
    default_theme = "dark",
    default_preset = "frosted_glass",
    layers = { enabled = 1 },
    dark = { brightness = 0.85, contrast = 1.1 },
  })

  -- 4. Success Notification
  if hl.notification then
    hl.notification.create({
      text = "hyprglass configured: frosted_glass",
      timeout = 3000,
      icon = "ok",
    })
  end

else
  if hl and hl.notification then
    hl.notification.create({
      text = "hyprglass plugin not loaded",
      timeout = 5000,
      icon = "warning",
    })
  end
end
-- =========================================================================
-- 2. HYPRLAND COMPOSITOR CONFIG & RULES
-- =========================================================================
hl.config({
  decoration = {
    blur = {
      new_optimizations = false, -- Required for proper glass/shader rendering
    },
  },
})

hl.window_rule({
  match = { class = "^(kitty)$" },
  opacity = "0.5 0.5"
})

-- =========================================================================
-- 3. AUTOSTART COMMANDS (Only fires once on compositor start)
-- =========================================================================
hl.on("hyprland.start", function ()
  hl.exec_cmd("waybar")
  hl.exec_cmd("waypaper --restore")
end)


