-- Window opacity rules
-- Catch-all first (lowest priority — gets overridden by more specific matches below)
hl.window_rule({
  match = { class = ".*" },
  opacity = "0.85 0.85"
})

hl.window_rule({
  match = { class = "^(kitty)$" },
  opacity = "0.85 0.85"
})

-- Full opacity exceptions — must come last so they win over the catch-all
hl.window_rule({
  match = {
    class = "^(steam_app_.*|wine|.*zenless_zone_zero.*|gamescope|org.prismlauncher.PrismLauncher|Spotify)$"
  },
  opacity = "1.0 1.0"
})


